@layer components {
  @supports ((anchor-name: --aui-slide-panel) and (anchor-scope: --aui-slide-panel)) {
    :where([data-control-family="tabs"][data-slot="panel"][data-slide="panel"][inert][data-slide-exiting][data-ending-style]) {
      display: block;
      position: absolute;
      top: var(--_tabs-panel-top);
      left: var(--_tabs-panel-left);
      right: auto;
      bottom: auto;
      width: var(--_tabs-panel-width);
      height: var(--_tabs-panel-height);
      margin: 0;
      overflow: clip;
      animation: aui-slide-exit-hold var(--duration-slow) var(--ease-emphasized) both;
    }

    @supports (height: anchor-size(height)) {
      :where([data-control-family="tabs"][data-slot="panel"][data-slide="panel"][inert][data-slide-exiting][data-ending-style]) {
        height: anchor-size(height);
      }
    }

    :where(
        [data-control-family="tabs"][data-slot="panel"][data-slide="panel"][inert][data-ending-style][data-activation-direction="right"]
      ) {
      translate: -100% 0;
    }

    :where(
        [data-control-family="tabs"][data-slot="panel"][data-slide="panel"][inert][data-ending-style][data-activation-direction="left"]
      ) {
      translate: 100% 0;
    }

    :where(
        [data-control-family="tabs"][data-slot="panel"][data-slide="panel"][inert][data-ending-style][data-activation-direction="down"]
      ) {
      translate: 0 -100%;
    }

    :where([data-control-family="tabs"][data-slot="panel"][data-slide="panel"][inert][data-ending-style][data-activation-direction="up"]) {
      translate: 0 100%;
    }

    :where(
        [data-control-family="tabs"][data-slot="root"]:has(> [data-slot="panel"][data-starting-style])
          > [data-slot="panel"][inert][data-ending-style]
      ) {
      translate: 0 0;
      transition: none;
    }

    :where([data-control-family="tabs"][data-slot="panel"][data-slide="panel"][data-starting-style]) {
      transition: none;
    }

    :where([data-control-family="tabs"][data-slot="root"][data-slide-starting] > [data-slot="panel"][data-slide="panel"]) {
      transition: none;
    }

    :where([data-control-family="tabs"][data-slot="root"][data-slide-starting] > [data-slot="panel"][inert]) {
      translate: 0 0;
    }

    :where(
        [data-control-family="tabs"][data-slot="root"][data-slide-starting]
          > [data-slot="panel"]:not([inert])[data-activation-direction="right"]
      ) {
      translate: 100% 0;
    }

    :where(
        [data-control-family="tabs"][data-slot="root"][data-slide-starting]
          > [data-slot="panel"]:not([inert])[data-activation-direction="left"]
      ) {
      translate: -100% 0;
    }

    :where(
        [data-control-family="tabs"][data-slot="root"][data-slide-starting]
          > [data-slot="panel"]:not([inert])[data-activation-direction="down"]
      ) {
      translate: 0 100%;
    }

    :where(
        [data-control-family="tabs"][data-slot="root"][data-slide-starting]
          > [data-slot="panel"]:not([inert])[data-activation-direction="up"]
      ) {
      translate: 0 -100%;
    }

    @supports (height: calc-size(auto, size)) {
      :where([data-control-family="tabs"][data-slot="root"][data-slide-starting] > [data-slot="panel"][data-slide="panel"]:not([inert])) {
        height: var(--aui-slide-prev-height, calc-size(auto, size));
      }
    }
  }
}

@layer components {
  :where([data-control-family="tabs"][data-slot="root"]) {
    position: relative;
    display: flex;
    flex-direction: column;
    --cui-tabs-trigger-radius: var(--radius-control);
    --cui-tabs-list-padding: calc(var(--spacing) * 1);
    --cui-tabs-list-radius: calc(
      var(--cui-tabs-trigger-radius) +
      clamp(0px, calc(var(--cui-tabs-trigger-radius) * 1000), var(--cui-tabs-list-padding))
    );
    --cui-tabs-list-background: var(--hover-fill);
    --cui-tabs-list-shadow: inset 0 0 0 var(--control-rim-width) var(--control-rim), var(--shadow-inset);
    --cui-tabs-list-backdrop-filter: none;
    --cui-tabs-indicator-background: var(--background);
    --cui-tabs-surface-background: var(--background);
    --cui-tabs-surface-radius: var(--radius-panel);
    --cui-tabs-foreground: var(--muted-foreground);
    --cui-tabs-active-foreground: var(--foreground);
    --cui-tabs-hover-foreground: var(--foreground);
    --cui-tabs-indicator-shadow: var(--shadow-sm);
    --cui-tabs-border-color: var(--border);
    --cui-tabs-border-width: var(--control-rim-width);
  }

  :where([data-control-family="tabs"][data-slot="root"][data-orientation="vertical"]) {
    flex-direction: row;
    gap: calc(var(--spacing) * 4);
  }

  :where([data-control-family="tabs"][data-slot="list"]) {
    --_tabs-trigger-radius-fit: min(var(--cui-tabs-trigger-radius), calc(var(--_tabs-trigger-h) / 2));
    position: relative;
    display: flex;
    min-height: calc(var(--_tabs-trigger-h) + var(--cui-tabs-list-padding) + var(--cui-tabs-list-padding));
    width: fit-content;
    align-items: center;
    gap: calc(var(--spacing) * 1);
    border-radius: min(var(--cui-tabs-list-radius), calc(var(--_tabs-trigger-h) / 2 + var(--cui-tabs-list-padding)));
    background: var(--cui-tabs-list-background);
    box-shadow: var(--cui-tabs-list-shadow);
    padding: var(--cui-tabs-list-padding);
    -webkit-backdrop-filter: var(--cui-tabs-list-backdrop-filter);
    backdrop-filter: var(--cui-tabs-list-backdrop-filter);
  }

  :where([data-control-family="tabs"][data-slot="indicator"]) {
    position: absolute;
    top: 50%;
    left: 0;
    z-index: 0;
    height: var(--_tabs-trigger-h);
    width: var(--active-tab-width);
    transform: translateX(var(--active-tab-left)) translateY(-50%);
    border-radius: var(--_tabs-trigger-radius-fit);
    background: var(--cui-tabs-indicator-background);
    box-shadow: var(--cui-tabs-indicator-shadow);
    /* Compositor transforms tear the strip while its width resizes. */
    transition:
      width var(--duration-base) var(--ease-standard),
      left var(--duration-base) var(--ease-standard),
      transform var(--duration-base) var(--ease-standard),
      background-color var(--duration-fast) var(--ease-standard),
      box-shadow var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="tabs"][data-slot="list"][data-orientation="vertical"]) {
    flex-direction: column;
    align-items: stretch;
  }

  :where([data-control-family="tabs"][data-slot="list"][data-orientation="vertical"] [data-slot="indicator"]) {
    top: 0;
    height: var(--active-tab-height);
    transform: translate(var(--active-tab-left), var(--active-tab-top));
  }

  :where([data-control-family="tabs"][data-slot="tab"]) {
    position: relative;
    z-index: 1;
    display: inline-flex;
    height: var(--_tabs-trigger-h);
    flex-shrink: 0;
    cursor: pointer;
    align-items: center;
    justify-content: center;
    gap: calc(var(--spacing) * 1.5);
    white-space: nowrap;
    border-radius: var(--_tabs-trigger-radius-fit);
    padding-inline: calc(var(--spacing) * 3.5);
    color: var(--cui-tabs-foreground);
    font-size: var(--text-label);
    font-weight: var(--font-weight-medium);
  }

  @media (hover: hover) {
    :where([data-control-family="tabs"][data-slot="tab"]:hover:not([data-disabled])) {
      color: var(--cui-tabs-hover-foreground);
    }
  }

  :where([data-control-family="tabs"][data-slot="tab"]:is([aria-selected="true"], [data-active])) {
    color: var(--cui-tabs-active-foreground);
  }

  :where([data-control-family="tabs"][data-slot="tab"][data-disabled]) {
    cursor: not-allowed;
    opacity: var(--disabled-opacity);
  }

  :where([data-control-family="tabs"][data-slot="list"][data-variant="browser"]) {
    --_tabs-browser-corner-double: calc(var(--_tabs-trigger-radius-fit) + var(--_tabs-trigger-radius-fit));
    --_tabs-browser-inset: calc(var(--_tabs-trigger-radius-fit) + var(--cui-tabs-surface-radius));
    min-height: calc(var(--_tabs-trigger-h) + var(--cui-tabs-list-padding));
    width: auto;
    align-items: flex-end;
    isolation: isolate;
    z-index: 1;
    --cui-tabs-list-background: transparent;
    --cui-tabs-list-shadow: inset 0 calc(-1 * var(--cui-tabs-border-width)) 0 var(--cui-tabs-border-color);
    --cui-tabs-active-foreground: var(--foreground);
    border-radius: var(--cui-tabs-list-radius) var(--cui-tabs-list-radius) 0 0;
  }

  :where([data-control-family="tabs"][data-slot="list"][data-variant="browser"] [data-slot="indicator"]) {
    --_tabs-browser-indicator-width: calc(var(--active-tab-width) + var(--_tabs-browser-corner-double));
    --_tabs-browser-indicator-x: calc(var(--active-tab-left) - var(--_tabs-trigger-radius-fit));
    background: none;
    box-shadow: none;
  }

  :where([data-control-family="tabs"][data-slot="list"][data-variant="browser"] [data-slot="indicator"])::before {
    content: "";
    position: absolute;
    inset: 0 var(--_tabs-trigger-radius-fit);
    border: var(--cui-tabs-border-width) solid var(--cui-tabs-border-color);
    border-bottom: none;
    border-radius: var(--_tabs-trigger-radius-fit) var(--_tabs-trigger-radius-fit) 0 0;
    background: var(--cui-tabs-surface-background);
  }

  :where([data-control-family="tabs"][data-slot="list"][data-variant="browser"] [data-slot="indicator"])::after {
    content: "";
    position: absolute;
    inset: auto 0 0;
    height: var(--_tabs-trigger-radius-fit);
    background:
      radial-gradient(
        circle at 0 -1px,
        transparent calc(var(--_tabs-trigger-radius-fit) - 0.5px),
        var(--cui-tabs-border-color) var(--_tabs-trigger-radius-fit) calc(var(--_tabs-trigger-radius-fit) + 0.5px),
        var(--cui-tabs-surface-background) calc(var(--_tabs-trigger-radius-fit) + 1px)
      )
      left / calc(var(--_tabs-trigger-radius-fit) + 1px) 100% no-repeat,
      radial-gradient(
        circle at 100% -1px,
        transparent calc(var(--_tabs-trigger-radius-fit) - 0.5px),
        var(--cui-tabs-border-color) var(--_tabs-trigger-radius-fit) calc(var(--_tabs-trigger-radius-fit) + 0.5px),
        var(--cui-tabs-surface-background) calc(var(--_tabs-trigger-radius-fit) + 1px)
      )
      right / calc(var(--_tabs-trigger-radius-fit) + 1px) 100% no-repeat,
      linear-gradient(var(--cui-tabs-surface-background) 0 0) center / calc(100% - var(--_tabs-browser-corner-double)) 100% no-repeat;
  }

  :where([data-control-family="tabs"][data-slot="list"][data-single="true"]) {
    min-height: auto;
    gap: 0;
    border-radius: 0;
    background: transparent;
    padding: 0;
  }

  :where([data-control-family="tabs"][data-slot="list"][data-single="true"] [data-slot="tab"]) {
    height: auto;
    cursor: default;
    border-radius: 0;
    padding-inline: 0;
    color: var(--muted-foreground);
  }

  :where([data-control-family="tabs"][data-slot="panel"]) {
    outline-style: none;
  }

  :where([data-control-family="tabs"][data-slot="root"][data-orientation="vertical"] > [data-slot="panel"]) {
    min-width: 0;
    flex: 1;
  }

  :where(
    [data-control-family="tabs"][data-slot="list"][data-orientation="horizontal"]:not([data-variant="browser"]) ~ [data-slot="panel"]
  ) {
    margin-block-start: calc(var(--spacing) * 3);
  }

  :where([data-control-family="tabs"][data-slot="list"][data-variant="browser"] ~ [data-slot="panel"]) {
    border: var(--cui-tabs-border-width) solid var(--cui-tabs-border-color);
    border-top: none;
    border-radius: 0 0 var(--cui-tabs-surface-radius) var(--cui-tabs-surface-radius);
    background: var(--cui-tabs-surface-background);
    padding: calc(var(--spacing) * 4);
  }

  :where([data-control-family="tabs"][data-slot="surface"]) {
    min-width: 0;
    border: var(--cui-tabs-border-width) solid var(--cui-tabs-border-color);
    border-radius: var(--cui-tabs-surface-radius);
    background: var(--cui-tabs-surface-background);
  }

  :where([data-control-family="tabs"][data-slot="list"][data-variant="browser"] [data-control-family="tabs"][data-slot="tab"]) {
    border-top-left-radius: var(--_tabs-trigger-radius-fit);
    border-top-right-radius: var(--_tabs-trigger-radius-fit);
    border-bottom-right-radius: 0;
    border-bottom-left-radius: 0;
  }

  @media (pointer: coarse) {
    :where([data-control-family="tabs"][data-slot="list"]:not([data-single="true"]) [data-slot="tab"])::after {
      content: "";
      position: absolute;
      inset: 50% 50%;
      translate: -50% -50%;
      inline-size: 100%;
      block-size: max(100%, var(--touch-target));
    }

    :where([data-control-family="tabs"][data-slot="list"][data-orientation="vertical"]:not([data-single="true"]) [data-slot="tab"])::after {
      inline-size: max(100%, var(--touch-target));
      block-size: 100%;
    }
  }
}

